def compute(vars):
    adjusted = vars["v1"]
    unadjusted = vars["v2"]
    if unadjusted == 0:
        return {"value": None, "trace": {"output_meta": {"currency": "USD", "scale": "million", "unit": "percentage"}}}
    change_ratio = (adjusted - unadjusted) / unadjusted
    return {
        "value": change_ratio * 100,
        "trace": {
            "adjusted_balance": adjusted,
            "unadjusted_balance": unadjusted,
            "change_ratio": change_ratio,
            "output_meta": {"currency": "USD", "scale": "million", "unit": "percentage"}
        }
    }
